package main

import (
	"testing"

	"github.com/emergingrobotics/erg/internal/cli"
	"github.com/emergingrobotics/erg/internal/config"
)

func TestChooseMode(t *testing.T) {
	cases := []struct {
		name string
		opts cli.Options
		loop config.LoopMode
		want mode
	}{
		{"observe shape wins", cli.Options{}, config.LoopObserve, modeObserve},
		{"observe wins even with -p", cli.Options{Oneshot: true}, config.LoopObserve, modeObserve},
		{"-p forces oneshot", cli.Options{Oneshot: true}, config.LoopInteractive, modeOneshot},
		{"oneshot shape", cli.Options{}, config.LoopOneshot, modeOneshot},
		{"default interactive", cli.Options{}, config.LoopInteractive, modeInteractive},
	}
	for _, c := range cases {
		if got := chooseMode(c.opts, c.loop); got != c.want {
			t.Fatalf("%s: chooseMode = %d, want %d", c.name, got, c.want)
		}
	}
}

func TestRunVersionAndBadFlag(t *testing.T) {
	if err := run([]string{"--version"}); err != nil {
		t.Fatalf("--version should return nil, got %v", err)
	}
	// An unknown flag: flag parsing fails and run swallows it (usage already printed).
	if err := run([]string{"--definitely-not-a-flag"}); err != nil {
		t.Fatalf("bad flag should be swallowed as nil, got %v", err)
	}
}

package app

import (
	"bytes"
	"context"
	"strings"
	"testing"

	"github.com/emergingrobotics/erg/internal/agent"
	"github.com/emergingrobotics/erg/internal/config"
	"github.com/emergingrobotics/erg/internal/terminal"
)

// buildMockApp builds an App on the offline mock provider with isolated session
// storage, exercising the full wiring path (resolve -> provider -> tools ->
// deps) without a network.
func buildMockApp(t *testing.T, ov config.Overrides) *App {
	t.Helper()
	t.Setenv("ERG_SESSIONS", t.TempDir())
	cfg := config.Default()
	if ov.Provider == "" {
		ov.Provider = "mock"
	}
	a, err := Build(context.Background(), cfg, ov, t.TempDir())
	if err != nil {
		t.Fatalf("build: %v", err)
	}
	return a
}

func TestBuildWiresMockProvider(t *testing.T) {
	a := buildMockApp(t, config.Overrides{})
	if a.deps.Provider.Model().Provider != "mock" {
		t.Fatalf("expected mock provider, got %q", a.deps.Provider.Model().Provider)
	}
	if len(a.deps.Tools) == 0 {
		t.Fatal("expected a non-empty toolset")
	}
}

func TestOneshotRunPersistsSession(t *testing.T) {
	a := buildMockApp(t, config.Overrides{})
	if err := a.Oneshot(context.Background(), "hello there"); err != nil {
		t.Fatalf("oneshot: %v", err)
	}
	// The session should be reloadable and contain the exchange.
	id := a.SessionID()
	_, items, err := a.sessions.Load(id)
	if err != nil {
		t.Fatalf("load session: %v", err)
	}
	if len(items) < 2 {
		t.Fatalf("expected user+assistant items, got %d", len(items))
	}
	var sawEcho bool
	for _, it := range items {
		if strings.Contains(it.Text, "[mock] hello there") {
			sawEcho = true
		}
	}
	if !sawEcho {
		t.Fatal("expected the mock echo in the session")
	}
}

func TestResumeLoadsPriorSession(t *testing.T) {
	a := buildMockApp(t, config.Overrides{})
	if err := a.Oneshot(context.Background(), "first"); err != nil {
		t.Fatalf("oneshot: %v", err)
	}
	id := a.SessionID()

	// A fresh app in the same session dir and cwd resumes it.
	b := &App{cfg: a.cfg, resolved: a.resolved, deps: a.deps, herdr: a.herdr, sessions: a.sessions, cwd: a.cwd}
	if err := b.Resume(id); err != nil {
		t.Fatalf("resume: %v", err)
	}
	if b.log.Len() == 0 {
		t.Fatal("resumed log should not be empty")
	}
}

func TestSlashClearResetsConversation(t *testing.T) {
	a := buildMockApp(t, config.Overrides{})
	if err := a.Oneshot(context.Background(), "populate"); err != nil {
		t.Fatalf("oneshot: %v", err)
	}
	oldID := a.SessionID()
	if a.log.Len() == 0 {
		t.Fatal("log should be populated before clear")
	}
	var buf bytes.Buffer
	if exit := a.slash(context.Background(), &buf, terminal.Styler{}, 60, "/clear"); exit {
		t.Fatal("/clear should not exit")
	}
	if a.log.Len() != 0 {
		t.Fatalf("log should be empty after /clear, got %d", a.log.Len())
	}
	if a.SessionID() == oldID {
		t.Fatal("/clear should start a new session id")
	}
}

func TestSlashCompactSummarizes(t *testing.T) {
	a := buildMockApp(t, config.Overrides{})
	if err := a.Oneshot(context.Background(), "some history"); err != nil {
		t.Fatalf("oneshot: %v", err)
	}
	var buf bytes.Buffer
	a.slash(context.Background(), &buf, terminal.Styler{}, 60, "/compact")

	// After compaction the window is a single summary seed.
	win := a.log.Window()
	if len(win) != 1 || win[0].Kind != agent.ItemSummarySeed {
		t.Fatalf("expected window to be one summary seed, got %+v", win)
	}
	if !strings.Contains(buf.String(), "compacted history") {
		t.Fatalf("expected compaction note, got %q", buf.String())
	}
}

func TestShowUsageAccumulates(t *testing.T) {
	a := buildMockApp(t, config.Overrides{})
	a.usage = agent.Usage{InputTokens: 100, OutputTokens: 40}
	var buf bytes.Buffer
	a.showUsage(&buf)
	if !strings.Contains(buf.String(), "100 in + 40 out = 140 total") {
		t.Fatalf("usage line wrong: %q", buf.String())
	}
}

func TestLastAssistantText(t *testing.T) {
	a := buildMockApp(t, config.Overrides{})
	if err := a.Oneshot(context.Background(), "hi there"); err != nil {
		t.Fatalf("oneshot: %v", err)
	}
	if got := a.lastAssistantText(); got != "[mock] hi there" {
		t.Fatalf("lastAssistantText = %q", got)
	}
}

func TestSwitchShape(t *testing.T) {
	t.Setenv("ERG_SESSIONS", t.TempDir())
	cfg := config.Default()
	cfg.DefaultProvider = "mock" // so any resolve builds the offline provider
	cfg.Shapes["reviewer"] = config.Shape{Name: "reviewer", Loop: config.LoopInteractive, System: "review carefully"}
	a, err := Build(context.Background(), cfg, config.Overrides{}, t.TempDir())
	if err != nil {
		t.Fatalf("build: %v", err)
	}
	var buf bytes.Buffer
	if err := a.switchShape(context.Background(), &buf, terminal.Styler{}, "reviewer"); err != nil {
		t.Fatalf("switchShape: %v", err)
	}
	if a.shape != "reviewer" {
		t.Fatalf("shape not switched: %q", a.shape)
	}
	if !strings.Contains(a.deps.System, "review carefully") {
		t.Fatalf("system not rebuilt for new shape:\n%s", a.deps.System)
	}
	if err := a.switchShape(context.Background(), &buf, terminal.Styler{}, "nope"); err == nil {
		t.Fatal("expected error for unknown shape")
	}
}

func TestSwitchShapePreservesLoopAndResetsUsage(t *testing.T) {
	t.Setenv("ERG_SESSIONS", t.TempDir())
	cfg := config.Default()
	cfg.DefaultProvider = "mock"
	cfg.Shapes["watch"] = config.Shape{Name: "watch", Loop: config.LoopObserve,
		Observe: &config.ObserveConfig{Source: config.SourceConfig{Kind: "stdin"}, Trigger: config.TriggerConfig{Kind: "every"}}}
	// Launch as an interactive session.
	a, err := Build(context.Background(), cfg, config.Overrides{}, t.TempDir())
	if err != nil {
		t.Fatalf("build: %v", err)
	}
	a.usage = agent.Usage{InputTokens: 500}
	var buf bytes.Buffer
	if err := a.switchShape(context.Background(), &buf, terminal.Styler{}, "watch"); err != nil {
		t.Fatalf("switchShape: %v", err)
	}
	// The launch loop (interactive) must be preserved, not replaced by observe.
	if a.Loop() != config.LoopInteractive {
		t.Fatalf("switching to an observe shape must not change the launch loop; got %q", a.Loop())
	}
	// A fresh shape starts a fresh usage tally.
	if a.usage.InputTokens != 0 {
		t.Fatalf("usage should reset on shape switch, got %+v", a.usage)
	}
}

func TestAutoCompactionTriggers(t *testing.T) {
	t.Setenv("ERG_SESSIONS", t.TempDir())
	cfg := config.Default()
	cfg.CompactAt = 1 // force compaction as soon as the window has any content
	a, err := Build(context.Background(), cfg, config.Overrides{Provider: "mock"}, t.TempDir())
	if err != nil {
		t.Fatalf("build: %v", err)
	}
	if err := a.Oneshot(context.Background(), "a message long enough to exceed one token"); err != nil {
		t.Fatalf("oneshot: %v", err)
	}
	if err := a.Oneshot(context.Background(), "second"); err != nil {
		t.Fatalf("oneshot: %v", err)
	}
	var seen bool
	for _, it := range a.log.Items() {
		if it.Kind == agent.ItemSummarySeed {
			seen = true
		}
	}
	if !seen {
		t.Fatal("expected auto-compaction to insert a summary seed")
	}
}

func TestObserveShapeReactsThroughApp(t *testing.T) {
	a := buildMockApp(t, config.Overrides{Shape: "telemetry-watcher"})
	if a.Loop() != config.LoopObserve {
		t.Fatalf("expected observe loop, got %q", a.Loop())
	}
	// Feed two events on stdin; the "every" trigger reacts to both.
	err := a.ObserveRun(context.Background(), strings.NewReader("event one\nevent two\n"))
	if err != nil {
		t.Fatalf("observe run: %v", err)
	}
	if a.meta.Reactions != 2 {
		t.Fatalf("expected 2 reactions, got %d", a.meta.Reactions)
	}
}

package config

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestResolveDefaults(t *testing.T) {
	cfg := Default()
	r, err := Resolve(cfg, Overrides{})
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	if r.Provider.Type != "local" {
		t.Fatalf("expected local provider by default, got %q", r.Provider.Type)
	}
	if r.Loop != LoopInteractive {
		t.Fatalf("expected interactive loop, got %q", r.Loop)
	}
	if !strings.Contains(r.System, "erg") {
		t.Fatal("system prompt should include the base")
	}
}

func TestResolveShapeAndOverrides(t *testing.T) {
	cfg := Default()
	r, err := Resolve(cfg, Overrides{Shape: "spec-implementer"})
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	if r.Loop != LoopOneshot || r.MaxTurns != 100 {
		t.Fatalf("shape not applied: %+v", r)
	}
	if !strings.Contains(r.System, "specification") {
		t.Fatal("shape system append missing")
	}

	// Override provider and model over the shape.
	r, err = Resolve(cfg, Overrides{Shape: "spec-implementer", Provider: "openai", Model: "gpt-x"})
	if err != nil {
		t.Fatalf("resolve override: %v", err)
	}
	if r.Provider.Type != "openai" || r.Model != "gpt-x" {
		t.Fatalf("overrides not applied: %+v", r)
	}
}

func TestResolveUnknownShapeAndProvider(t *testing.T) {
	cfg := Default()
	if _, err := Resolve(cfg, Overrides{Shape: "nope"}); err == nil {
		t.Fatal("expected unknown shape error")
	}
	if _, err := Resolve(cfg, Overrides{Provider: "nope"}); err == nil {
		t.Fatal("expected unknown provider error")
	}
}

func TestLoadMergesFile(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.json")
	os.WriteFile(path, []byte(`{"default_provider":"openai","shapes":{"x":{"loop":"oneshot","system":"custom"}}}`), 0o644)
	t.Setenv("ERG_CONFIG", path)

	cfg, err := Load()
	if err != nil {
		t.Fatalf("load: %v", err)
	}
	if cfg.DefaultProvider != "openai" {
		t.Fatalf("merge failed: %q", cfg.DefaultProvider)
	}
	if _, ok := cfg.Shapes["x"]; !ok {
		t.Fatal("user shape not merged")
	}
	// Built-in shapes survive the merge.
	if _, ok := cfg.Shapes["design-partner"]; !ok {
		t.Fatal("default shapes should remain after merge")
	}
}

func TestLoadErrorsWhenExplicitConfigMissing(t *testing.T) {
	missing := filepath.Join(t.TempDir(), "does-not-exist.json")
	t.Setenv("ERG_CONFIG", missing)

	if _, err := Load(); err == nil {
		t.Fatal("expected error when ERG_CONFIG names a missing file")
	}
}

func TestResolveComposesSkills(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "deploy")
	os.MkdirAll(dir, 0o755)
	os.WriteFile(filepath.Join(dir, "SKILL.md"),
		[]byte("---\nname: deploy\ndescription: how to ship\n---\nRun make deploy."), 0o644)

	cfg := Default()
	cfg.Shapes["shipper"] = Shape{Name: "shipper", Loop: LoopOneshot, Skills: []string{dir}}
	r, err := Resolve(cfg, Overrides{Shape: "shipper"})
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	for _, want := range []string{"# Skills", "Skill: deploy", "Run make deploy."} {
		if !strings.Contains(r.System, want) {
			t.Fatalf("missing %q in system prompt:\n%s", want, r.System)
		}
	}
}

func TestResolveMissingSkillErrors(t *testing.T) {
	cfg := Default()
	cfg.Shapes["x"] = Shape{Name: "x", Skills: []string{"/no/such/skill/dir"}}
	if _, err := Resolve(cfg, Overrides{Shape: "x"}); err == nil {
