func decodeAll(t *testing.T, s string) []keyEvent {
	t.Helper()
	br := bufio.NewReader(strings.NewReader(s))
	var out []keyEvent
	for {
		k, err := decode(br)
		if err != nil {
			break
		}
		out = append(out, k)
	}
	return out
}

func TestDecodeKeys(t *testing.T) {
	cases := map[string]keyKind{
		"a":       keyRune,
		"\r":      keyEnter,
		"\n":      keyEnter,
		"\x7f":    keyBackspace,
		"\x03":    keyInterrupt,
		"\x04":    keyEOF,
		"\x01":    keyHome,
		"\x05":    keyEnd,
		"\x1b[A":  keyUp,
		"\x1b[B":  keyDown,
		"\x1b[C":  keyRight,
		"\x1b[D":  keyLeft,
		"\x1b[H":  keyHome,
		"\x1b[3~": keyDelete,
		"\x1bOA":  keyUp, // application cursor mode
	}
	for input, want := range cases {
		got := decodeAll(t, input)
		if len(got) == 0 || got[0].kind != want {
			t.Fatalf("decode %q: got %+v, want kind %d", input, got, want)
