func TestReaderSourceEmitsLines(t *testing.T) {
	src, err := BuildSource(config.SourceConfig{Kind: "stdin"}, strings.NewReader("a\nb\nc\n"))
	if err != nil {
		t.Fatalf("build: %v", err)
	}
	ch, err := src.Events(context.Background())
	if err != nil {
		t.Fatalf("events: %v", err)
	}
	var got []string
	for ev := range ch {
		got = append(got, ev.Text)
	}
	if strings.Join(got, ",") != "a,b,c" {
		t.Fatalf("got %v", got)
	}
}

func TestMatchTrigger(t *testing.T) {
	tr, err := BuildTrigger(config.TriggerConfig{Kind: "match", Pattern: `(?i)error`})
	if err != nil {
		t.Fatalf("build: %v", err)
	}
	if !tr.Match(Event{Text: "an ERROR happened"}) {
		t.Fatal("should match")
	}
	if tr.Match(Event{Text: "all good"}) {
		t.Fatal("should not match")
	}
}

func TestDriverReactsOnlyToMatches(t *testing.T) {
	src, _ := BuildSource(config.SourceConfig{Kind: "stdin"},
		strings.NewReader("ok\nERROR: disk full\nok again\nERROR: oom\n"))
	tr, _ := BuildTrigger(config.TriggerConfig{Kind: "match", Pattern: "ERROR"})

	var mu sync.Mutex
	var prompts []string
	var statuses []agent.AgentStatus

	d := &Driver{
		Source:  src,
		Trigger: tr,
		Prompt:  "Event: {{.Event}}",
		React: func(_ context.Context, prompt string) (agent.AgentStatus, error) {
			mu.Lock()
			prompts = append(prompts, prompt)
			mu.Unlock()
			return agent.StatusIdle, nil
		},
		Status: func(s agent.AgentStatus) {
			mu.Lock()
			statuses = append(statuses, s)
			mu.Unlock()
		},
	}
	if err := d.Run(context.Background()); err != nil {
		t.Fatalf("run: %v", err)
	}

	if len(prompts) != 2 {
		t.Fatalf("expected 2 reactions, got %d: %v", len(prompts), prompts)
	}
	if prompts[0] != "Event: ERROR: disk full" {
		t.Fatalf("prompt render wrong: %q", prompts[0])
	}
	// First status is idle (watching), last is done (stream ended).
	if statuses[0] != agent.StatusIdle || statuses[len(statuses)-1] != agent.StatusDone {
		t.Fatalf("status lifecycle wrong: %v", statuses)
	}
	// A reaction flips to working then back to idle.
	if !containsStatus(statuses, agent.StatusWorking) {
		t.Fatal("expected a working status during a reaction")
	}
}

func TestDriverReportsBlockedReaction(t *testing.T) {
	src, _ := BuildSource(config.SourceConfig{Kind: "stdin"}, strings.NewReader("go\n"))
	tr, _ := BuildTrigger(config.TriggerConfig{Kind: "every"})
	var mu sync.Mutex
	var statuses []agent.AgentStatus
	d := &Driver{
		Source:  src,
		Trigger: tr,
		React:   func(context.Context, string) (agent.AgentStatus, error) { return agent.StatusBlocked, nil },
		Status:  func(s agent.AgentStatus) { mu.Lock(); statuses = append(statuses, s); mu.Unlock() },
	}
	if err := d.Run(context.Background()); err != nil {
		t.Fatalf("run: %v", err)
	}
	if !containsStatus(statuses, agent.StatusBlocked) {
		t.Fatalf("a blocked reaction should report blocked, got %v", statuses)
	}
}

func TestDriverCancellation(t *testing.T) {
	// A blocking source (never sends) so Run only ends on cancellation.
	pr, pw := io.Pipe()
	defer pw.Close()
	src := &readerSource{r: pr}
	tr, _ := BuildTrigger(config.TriggerConfig{Kind: "every"})

	ctx, cancel := context.WithCancel(context.Background())
	done := make(chan error, 1)
	go func() {
		done <- (&Driver{Source: src, Trigger: tr, React: func(context.Context, string) (agent.AgentStatus, error) { return agent.StatusIdle, nil }}).Run(ctx)
	}()
	cancel()
	select {
	case err := <-done:
		if err == nil {
			t.Fatal("expected cancellation error")
		}
	case <-time.After(2 * time.Second):
		t.Fatal("Run did not return after cancel")
	}
}

func containsStatus(ss []agent.AgentStatus, want agent.AgentStatus) bool {
	for _, s := range ss {
		if s == want {
			return true
		}
	}
	return false
}

package herdr

import (
	"bufio"
	"encoding/json"
	"net"
	"path/filepath"
	"sync"
	"testing"
	"time"

	"github.com/emergingrobotics/erg/internal/agent"
)

type recordedReq struct {
	Method string         `json:"method"`
	Params map[string]any `json:"params"`
}

// fakeHerdr is an in-test socket server speaking herdr's newline-JSON protocol.
type fakeHerdr struct {
	ln   net.Listener
	mu   sync.Mutex
	reqs []recordedReq
}

func startFakeHerdr(t *testing.T) (*fakeHerdr, string) {
	t.Helper()
	sock := filepath.Join(t.TempDir(), "herdr.sock")
	ln, err := net.Listen("unix", sock)
	if err != nil {
		t.Fatalf("listen: %v", err)
	}
	f := &fakeHerdr{ln: ln}
	go f.serve()
	t.Cleanup(func() { ln.Close() })
	return f, sock
}

func (f *fakeHerdr) serve() {
	for {
		conn, err := f.ln.Accept()
		if err != nil {
			return
		}
		go func() {
			defer conn.Close()
			sc := bufio.NewScanner(conn)
			if !sc.Scan() {
				return
			}
			var req struct {
				ID     string         `json:"id"`
				Method string         `json:"method"`
				Params map[string]any `json:"params"`
			}
			if err := json.Unmarshal(sc.Bytes(), &req); err != nil {
				return
			}
			f.mu.Lock()
			f.reqs = append(f.reqs, recordedReq{Method: req.Method, Params: req.Params})
			f.mu.Unlock()
			resp, _ := json.Marshal(map[string]any{"id": req.ID, "result": map[string]any{}})
			conn.Write(append(resp, '\n'))
		}()
	}
}

func (f *fakeHerdr) recorded() []recordedReq {
	f.mu.Lock()
	defer f.mu.Unlock()
	out := make([]recordedReq, len(f.reqs))
	copy(out, f.reqs)
	return out
}

func TestClientDisabledWithoutEnv(t *testing.T) {
	c := New(Env{})
	if c.Enabled() {
		t.Fatal("client should be disabled without env")
	}
	c.ReportStatus(agent.StatusWorking) // must be a silent no-op
}

func TestReportStatusDedupsAndReports(t *testing.T) {
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "w1:p1"})

	c.ReportStatus(agent.StatusWorking)
	c.ReportStatus(agent.StatusWorking) // duplicate, suppressed
	c.ReportStatus(agent.StatusIdle)

	waitFor(t, func() bool { return len(f.recorded()) >= 2 })
	reqs := f.recorded()
	if len(reqs) != 2 {
		t.Fatalf("expected 2 reports (dedup), got %d: %+v", len(reqs), reqs)
	}
	if reqs[0].Method != "pane.report_agent" || reqs[0].Params["state"] != "working" {
		t.Fatalf("first report wrong: %+v", reqs[0])
	}
	if reqs[1].Params["state"] != "idle" {
		t.Fatalf("second report wrong: %+v", reqs[1])
	}
	if reqs[0].Params["pane_id"] != "w1:p1" {
		t.Fatalf("pane_id not sent (herdr requires pane_id, not pane): %+v", reqs[0].Params)
	}
}

func TestReportBlocked(t *testing.T) {
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})
	c.ReportStatus(agent.StatusBlocked)
	waitFor(t, func() bool { return len(f.recorded()) >= 1 })
	if got := f.recorded()[0].Params["state"]; got != "blocked" {
		t.Fatalf("expected state blocked, got %v", got)
	}
}

func TestReportDoneReleasesAgent(t *testing.T) {
	// "done" is not a valid pane state; it must relinquish agent authority.
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})
	c.ReportStatus(agent.StatusDone)
	waitFor(t, func() bool { return len(f.recorded()) >= 1 })
	req := f.recorded()[0]
	if req.Method != "pane.release_agent" {
		t.Fatalf("done should call pane.release_agent, got %s", req.Method)
	}
	if req.Params["pane_id"] != "p" {
		t.Fatalf("pane_id not sent: %+v", req.Params)
	}
}

func TestReleaseReleasesAgentAfterIdle(t *testing.T) {
	// A normal exit leaves the pane idle; Release must still relinquish agent
	// authority so herdr drops erg from the panel.
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})
	c.ReportStatus(agent.StatusIdle)
	c.Release()
	waitFor(t, func() bool { return len(f.recorded()) >= 2 })
	last := f.recorded()[1]
	if last.Method != "pane.release_agent" {
		t.Fatalf("Release should call pane.release_agent, got %s", last.Method)
	}
	if last.Params["pane_id"] != "p" {
		t.Fatalf("pane_id not sent: %+v", last.Params)
	}
}

func TestReleaseDisabledIsNoop(t *testing.T) {
	c := New(Env{})
	c.Release() // must not panic or dial
}

func TestReportMetadata(t *testing.T) {
	f, sock := startFakeHerdr(t)
	c := New(Env{Active: true, SocketPath: sock, PaneID: "p"})
	c.ReportMetadata(map[string]string{"shape": "spec-implementer", "model": "mock"})

	waitFor(t, func() bool { return len(f.recorded()) >= 1 })
	reqs := f.recorded()
	if reqs[0].Method != "pane.report_metadata" {
		t.Fatalf("expected metadata method, got %s", reqs[0].Method)
	}
	tokens, ok := reqs[0].Params["tokens"].(map[string]any)
	if !ok || tokens["shape"] != "spec-implementer" {
		t.Fatalf("tokens not sent: %+v", reqs[0].Params)
	}
}

func TestReportSurvivesMissingSocket(t *testing.T) {
	// No server listening: the report must not panic or block.
	c := New(Env{Active: true, SocketPath: filepath.Join(t.TempDir(), "absent.sock"), PaneID: "p"})
